import XCTest
import OnymTransport
@testable import OnymMesh

/// Coded frames (spec §4c), against `Fixtures/mesh-v1-vectors.json`'s
/// "coded" section — generated by a Python implementation independent of
/// both apps. Android checks the same file.
final class MeshCodingTests: XCTestCase {
    private var coded: [String: Any]!
    private var vectors: [String: Any]!

    override func setUpWithError() throws {
        let url = try XCTUnwrap(Bundle.module.url(forResource: "mesh-v1-vectors", withExtension: "json", subdirectory: "Fixtures"))
        vectors = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
        coded = try XCTUnwrap(vectors["coded"] as? [String: Any])
    }

    private func string(_ key: String) -> String { coded[key] as! String }

    func testCoefficientsMatchTheVectors() throws {
        let c = try XCTUnwrap(coded["coefficients"] as? [String: Any])
        let values = MeshFountain.coefficients(
            envelopeID: UInt16(c["envelopeID"] as! String, radix: 16)!,
            index: UInt16(c["index"] as! Int),
            k: c["k"] as! Int
        )
        XCTAssertEqual(values.map(Int.init), c["values"] as! [Int])
    }

    func testEncoderFramesMatchTheVectors() throws {
        let envelope = hex(string("envelopeHex"))
        let envelopeID = UInt16(string("envelopeID"), radix: 16)!
        let encoder = try XCTUnwrap(MeshFountain.Encoder(envelope: envelope, envelopeID: envelopeID))
        XCTAssertEqual(encoder.k, coded["k"] as! Int)
        let epoch = UInt32(vectors["epoch"] as! Int)
        let tag = try XCTUnwrap(MeshTag(bytes: hex(((vectors["tags"] as! [[String: Any]])[0]["tag"] as! String))))
        let frames = (coded["frames"] as! [String]).enumerated().map { i, _ in
            MeshCodedFrame(
                epochLow: UInt8(epoch & 0xFF), tag: tag, envelopeID: envelopeID,
                k: UInt8(encoder.k), index: UInt16(i), symbol: encoder.symbol(index: UInt16(i))
            ).bytes
        }
        XCTAssertEqual(frames, (coded["frames"] as! [String]).map(hex))
    }

    /// Any k independent frames rebuild it: here, only repair frames, from
    /// the vectors, in reverse.
    func testDecodesFromRepairFramesAlone() throws {
        let frames = (coded["frames"] as! [String]).map(hex).compactMap(MeshCodedFrame.init(bytes:))
        let k = coded["k"] as! Int
        var decoder = MeshFountain.Decoder(k: k, envelopeID: frames[0].envelopeID)
        var out: Data?
        for frame in frames.filter({ Int($0.index) >= k }).reversed() {
            out = decoder.add(index: frame.index, symbol: frame.symbol) ?? out
        }
        XCTAssertEqual(out, hex(string("envelopeHex")))
    }

    /// Any k of a stream of frames, in any order — the property the speed
    /// comes from. Every k-subset of the first 2k frames of a real-sized
    /// envelope, shuffled, should decode (GF(256) makes a dependent set
    /// rare; allow it, but not often).
    func testAnyKFramesInAnyOrderDecode() throws {
        let envelope = Data((0..<500).map { UInt8(truncatingIfNeeded: $0 &* 37) })
        let encoder = try XCTUnwrap(MeshFountain.Encoder(envelope: envelope, envelopeID: 0x1234))
        var failures = 0
        for trial in 0..<50 {
            var indices = Array(0..<UInt16(encoder.k * 2)).shuffled()
            indices = Array(indices.prefix(encoder.k + 1))
            var decoder = MeshFountain.Decoder(k: encoder.k, envelopeID: 0x1234)
            var out: Data?
            for i in indices { out = decoder.add(index: i, symbol: encoder.symbol(index: i)) ?? out }
            if out != envelope { failures += 1 }
            _ = trial
        }
        XCTAssertLessThanOrEqual(failures, 1, "k+1 random frames should almost always decode")
    }

    func testRedundantFramesAreIgnored() throws {
        let encoder = try XCTUnwrap(MeshFountain.Encoder(envelope: Data(repeating: 9, count: 40), envelopeID: 7))
        var decoder = MeshFountain.Decoder(k: encoder.k, envelopeID: 7)
        XCTAssertNil(decoder.add(index: 0, symbol: encoder.symbol(index: 0)))
        XCTAssertNil(decoder.add(index: 0, symbol: encoder.symbol(index: 0)))
        XCTAssertEqual(decoder.rank, 1)
    }

    func testEnvelopeBinaryRoundTripsWithTheVectors() throws {
        let json = try JSONSerialization.data(withJSONObject: coded["sealedEnvelopeJSON"]!)
        let binary = try XCTUnwrap(MeshEnvelope.binary(fromJSON: json))
        XCTAssertEqual(binary, hex(string("sealedEnvelopeBinaryHex")))
        let back = try XCTUnwrap(MeshEnvelope.json(fromBinary: binary))
        let a = try JSONSerialization.jsonObject(with: back) as! NSDictionary
        XCTAssertEqual(a, coded["sealedEnvelopeJSON"] as! NSDictionary)
    }

    func testEnvelopeRejectsWhatIsntOne() {
        XCTAssertNil(MeshEnvelope.binary(fromJSON: Data("{}".utf8)))
        XCTAssertNil(MeshEnvelope.json(fromBinary: Data([1, 2, 3])))
        XCTAssertNil(MeshEnvelope.json(fromBinary: Data([2]) + Data(count: 200)))
    }

    /// Python's raw DEFLATE inflates here: the wire contract, not this
    /// implementation's own output, is what's checked.
    func testPayloadExpandsAnIndependentlyDeflatedPayload() throws {
        XCTAssertEqual(MeshPayload.expand(hex(string("compressedPlaintextHex"))), hex(string("payloadHex")))
        let json = Data(#"{"a":1}"#.utf8)
        XCTAssertEqual(MeshPayload.expand(json), json, "unmarked plaintext passes through")
        let compressed = try XCTUnwrap(MeshPayload.compress(hex(string("payloadHex"))))
        XCTAssertEqual(MeshPayload.expand(compressed), hex(string("payloadHex")))
        XCTAssertNil(MeshPayload.expand(Data([0x01, 0xFF, 0xFF])), "garbage after the marker")
    }

    /// End to end through the transport: coded frames, shuffled with
    /// repeats, become the inbox's JSON envelope.
    func testTransportDeliversCodedFramesAsJSON() async throws {
        struct NoSource: MeshFrameSource { func frames() -> AsyncStream<Data> { AsyncStream { _ in } } }
        let inbox = TransportInboxID(rawValue: "aabbccddeeff0011")
        let pairKey = Data(repeating: 0x42, count: 32)
        let now = Date(timeIntervalSince1970: 1_794_398_400)
        let transport = MeshInboxTransport(source: NoSource(), contacts: { [MeshContact(inbox: inbox, pairKey: pairKey)] }, now: { now })
        let json = try JSONSerialization.data(withJSONObject: coded["sealedEnvelopeJSON"]!, options: [.sortedKeys])
        let binary = try XCTUnwrap(MeshEnvelope.binary(fromJSON: json))
        let encoder = try XCTUnwrap(MeshFountain.Encoder(envelope: binary, envelopeID: 0x0102))
        let epoch = MeshEpoch.number(at: now)
        let tag = MeshTag.derive(pairKey: pairKey, epoch: epoch)
        let frames = (UInt16(encoder.k)..<UInt16(encoder.k * 3)).map {
            MeshCodedFrame(epochLow: UInt8(epoch & 0xFF), tag: tag, envelopeID: 0x0102, k: UInt8(encoder.k), index: $0, symbol: encoder.symbol(index: $0)).bytes
        }.shuffled()

        let stream = transport.subscribe(inbox: inbox)
        try await Task.sleep(nanoseconds: 50_000_000)
        for f in frames + frames { await transport.receive(f) }
        await transport.unsubscribe(inbox: inbox)
        var out: [InboundInbox] = []
        for await m in stream { out.append(m) }
        XCTAssertEqual(out.count, 1, "delivered once despite the repeats")
        XCTAssertEqual(out.first?.delivery, .bluetooth)
        let a = try JSONSerialization.jsonObject(with: out.first!.payload) as! NSDictionary
        XCTAssertEqual(a, coded["sealedEnvelopeJSON"] as! NSDictionary)
    }
}
